  // spellchecker: ignore-next-line
  @@unique([shopping_mall_customer_id, token], map: "shopping_mall_customer_password_resets_shopping_mall_c_a7f19076")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, created_at], map: "shopping_mall_customer_password_resets_shopping_mall_c_08e0cfed")
}

