models.description:
Password reset tokens with expiration for customer account recovery.

This table enables secure, time-limited password reset functionality for customers. Each record represents a single password reset request, tied to a specific customer account and invalidated after expiration. The token is a cryptographically random string issued upon request and validated during reset. Expiration ensures security by limiting the window of vulnerability. This table is immutable after creation and referenced only by the authentication service. The customer_id foreign key ensures each reset is tied to an authentic customer account.

@see shopping_mall_customers.id for customer account linkage.
@see shopping_mall_customer_sessions for active session tracking.
@see shopping_mall_customer_email_verifications for email verification workflow.

Images associated with a product. These are subsidiary entities managed only through the parent product. Images are ordered by sort_order and displayed during product viewing. Deleted when parent product is deleted, never independently.

Each image is referenced by exactly one product via foreign key. No image can exist without a parent product. Images are not searchable independently, nor editable independently—only through product edit flows.

@link shopping_mall_products.id

schemas.schema-02-actors.prisma:
/// Registered customer accounts with email/password credentials and
/// authentication metadata. This is an actor table representing a true
/// identity record in the system that owns sessions and credentials.
/// Customers can browse products, make purchases, manage addresses, create
/// wishlists, and write reviews. When a customer deletes their account, this
/// record is soft-deleted but preserves all associated order history for
/// legal compliance. The email and password_hash are required for
/// authentication. Profile data such as name and phone are stored in
/// separate tables.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used for authentication and communication. Must be a
  /// valid email format.
  email String

  /// Hashed password for secure authentication. Never store plaintext
  /// passwords.
  password_hash String

  /// Timestamp when this customer account was created. Always recorded upon
  /// registration.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last modification to this account. Updated whenever any
  /// field changes.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp. Null if account is active. When non-null,
  /// account is inactive but preserved for audit and order history linkage.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions             shopping_mall_customer_sessions[]
  passwordResets       shopping_mall_customer_password_resets[]
  emailVerification    shopping_mall_customer_email_verifications?
  emailVerifications   shopping_mall_seller_email_verifications[]
  snapshots            shopping_mall_snapshots[]
  orders               shopping_mall_orders[]
  cancellationRequests shopping_mall_cancellation_requests[]
  refundRequests       shopping_mall_refund_requests[]
  reviews              shopping_mall_reviews[]
  reviewSnapshots      shopping_mall_review_snapshots[]
  reviewVotes          shopping_mall_review_votes[]

  @@unique([email])
  @@index([created_at])
  @@index([updated_at])
  @@index([deleted_at])
  @@index([email, deleted_at])
}

/// JWT access and refresh tokens for authenticated customer sessions with
/// expiration tracking. This table is an append-only audit trail of login
/// events for customer actors, ensuring security compliance by capturing
/// connection metadata (IP, referrer) and enforcing token expiration.
///
/// This table is a child of shopping_mall_customers. Each customer can have
/// multiple sessions (1:N relationship), representing concurrent or
/// historical logins. Sessions are never modified or deleted - only
/// appended. They can be invalidated by system policy or customer logout,
/// but their records remain in the database for audit.
///
/// When a customer logs in, a new session record is created. The session
/// remains valid until either:
/// - The access token expires (30 minutes)
/// - The refresh token expires (30 days)
/// - The user logs out (system invalidates the refresh token)
/// - The admin suspends the customer account
///
/// Never use this table for storing any business data. It exists solely for
/// authentication security and audit purposes.
///
/// @\link shopping_mall_customers.id
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customer_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer identifier this session belongs to. {@link
  /// shopping_mall_customers.id}.
  shopping_mall_customer_id String @db.Uuid

  /// JWT access token used for API authentication. Expires 30 minutes after
  /// creation.
  access_token String

  /// JWT refresh token used to obtain new access tokens. Expires 30 days after
  /// creation.
  refresh_token String

  /// Client IP address from which the login request originated.
  ip String

  /// Full URL of the page where login occurred.
  href String @db.VarChar(80000)

  /// Referrer URL that led the user to the login page.
  referrer String? @db.VarChar(80000)

  /// Timestamp when this session was created and login occurred.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this session expires and becomes invalid. Always set to 30
  /// days after created_at for refresh token.
  expired_at DateTime @db.Timestamptz

  /// Flag indicating whether this session is still valid. True until token
  /// expires or is invalidated by logout/admin action.
  is_active Boolean

  //----
  // RELATIONS
  //----
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, created_at], map: "shopping_mall_customer_sessions_shopping_mall_customer_adefa402")
  @@index([access_token])
  @@index([refresh_token])
  @@index([expired_at])
  @@index([ip(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Password reset tokens with expiration for customer account recovery.
