  suspended_at DateTime? @db.Timestamptz

  /// Timestamp when the seller account was registered.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the seller account is logically deleted. If null, account
