    data: customers.map((customer) => ({
      email: customer.email,
      created_at: toISOStringSafe(customer.created_at),
    })),
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  };
}

