export async function postShoppingMallAdminResetRequest(props: {
  admin: AdminPayload;
  body: IShoppingMallCustomerPasswordReset;
}): Promise<IShoppingMallCustomerPasswordReset> {
  // Validate email format
  if (!typia.is<string & tags.Format<"email">>(props.body.email)) {
    throw new HttpException("Invalid email format", 400);
  }
  const oneHourAgo = toISOStringSafe(new Date(Date.now() - 60 * 60 * 1000));
  const recentRequests = await MyGlobal.prisma.shopping_mall_system_logs.count({
    where: {
      event_type: "PASSWORD_RESET_REQUEST", // Fixed: 'event_type' from schema, not 'event_name'
      metadata: { contains: props.body.email },
      created_at: { gte: oneHourAgo },
    },
  });
  if (recentRequests >= 5) {
    throw new HttpException("Rate limit exceeded", 429);
  }
  const transaction = MyGlobal.prisma.$transaction(async (prisma) => {
    // Look up customer and seller
    const customer = await prisma.shopping_mall_customers.findFirst({
      where: { email: props.body.email, deleted_at: null },
    });
    const seller = await prisma.shopping_mall_sellers.findFirst({
      where: { email: props.body.email, deleted_at: null },
    });
    // Determine user ID and table
    const userId = customer?.id ?? seller?.id;
    // Invalidate existing reset tokens for this email
    if (customer) {
      await prisma.shopping_mall_customer_password_resets.updateMany({
        where: { shopping_mall_customer_id: props.body.email },
        data: { token: "" }, // Use token field to mark as invalid, since deleted_at doesn't exist
      });
    }
    if (seller) {
      await prisma.shopping_mall_seller_password_resets.updateMany({
        where: { shopping_mall_seller_id: props.body.email },
        data: { token: "" },
      });
    }
    // Generate token
    const token_id: string & tags.Format<"uuid"> = v4();
    const issued_at: string & tags.Format<"date-time"> = toISOStringSafe(
      new Date(),
    );
    const expires_at: string & tags.Format<"date-time"> = toISOStringSafe(
      new Date(Date.now() + 60 * 60 * 1000),
    );
    // Create reset record
    if (customer) {
      await prisma.shopping_mall_customer_password_resets.create({
        data: {
          id: token_id,
          shopping_mall_customer_id: customer.id,
          token: token_id,
          expires_at,
          created_at: issued_at,
          updated_at: issued_at,
        },
      });
    } else if (seller) {
      await prisma.shopping_mall_seller_password_resets.create({
        data: {
          id: token_id,
          shopping_mall_seller_id: seller.id,
          token: token_id,
          expires_at,
          created_at: issued_at,
          updated_at: issued_at,
        },
      });
    } else {
      // Dummy reset record for security
      const dummyUserId: string & tags.Format<"uuid"> = v4();
      await prisma.shopping_mall_customer_password_resets.create({
        data: {
          id: token_id,
          shopping_mall_customer_id: dummyUserId,
          token: token_id,
          expires_at,
          created_at: issued_at,
          updated_at: issued_at,
        },
      });
    }
    // Log request
    await prisma.shopping_mall_system_logs.create({
      data: {
        id: v4(), // Required field missing
        event_type: "PASSWORD_RESET_REQUEST",
        created_at: toISOStringSafe(new Date()),
        severity: "info",
        metadata: JSON.stringify({
          email: props.body.email,
          ip: "unknown",
          user_agent: "unknown",
        }),
      },
    });
    // Return response matching IShoppingMallCustomerPasswordReset: only email
    return { email: props.body.email };
  });
  return await transaction;
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postShoppingMallAuthCustomerRefresh(props: {
  body: IShoppingMallCustomer.IRefresh;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  // The refresh token is the raw string value of the request body, not a property
  const refreshTokenInput = props.body as string;
  // Validate refresh token using jwt.verify
  let decoded: {
    id: string;
    session_id: string;
    type: "customer";
  };
  try {
    decoded = jwt.verify(refreshTokenInput, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    }) as typeof decoded;
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  // Validate token type
  if (decoded.type !== "customer") {
    throw new HttpException("Invalid token type", 403);
  }
  // Validate session existence and status
  const session =
    await MyGlobal.prisma.shopping_mall_customer_sessions.findFirst({
      where: {
        id: decoded.session_id,
        shopping_mall_customer_id: decoded.id,
        is_active: true,
      },
    });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  // Validate customer account not deleted
  const customer =
    await MyGlobal.prisma.shopping_mall_customers.findUniqueOrThrow({
      where: { id: decoded.id },
    });
  if (customer.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }
  // Generate new tokens with SAME session_id
  const accessExpires = new Date(Date.now() + 30 * 60 * 1000); // 30 minutes
  const refreshExpires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days
  // Create properly formatted ISO string dates with tags.Format<"date-time">
  const newAccessExpires = toISOStringSafe(accessExpires);
  const newRefreshExpires = toISOStringSafe(refreshExpires);
  // Generate new tokens
  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "30m", issuer: "autobe" },
  );
  const generatedRefreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "30d", issuer: "autobe" },
  );
  // Update session with new expiration
  await MyGlobal.prisma.shopping_mall_customer_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshExpires },
  });
  // Return authorized response with new tokens
  return {
    token: {
      access: accessToken,
      refresh: generatedRefreshToken,
      expired_at: newAccessExpires,
      refreshable_until: newRefreshExpires,
    },
  };
}

