  /**
   * Retrieve the complete details of a specific shipment using its unique identifier.
   *
   * This endpoint returns immutable shipment information from the shopping_mall_shipments table, including the carrier name, tracking number, shipment status, and creation timestamp. The shipment record is preserved exactly as created by the seller and cannot be modified after creation, ensuring a persistent audit trail for delivery tracking.
   *
   * The status field indicates the current phase of the shipment: 'shipped' (initial status upon creation), 'delivered' (confirmed by customer), or 'auto-delivered' (automatically set after 14 days without customer confirmation). This enterprise-grade tracking system prevents any post-creation tampering with shipment information, maintaining integrity for dispute resolution and compliance purposes.
   *
   * Authorized actors include customers who placed the order and sellers who created the shipment, who can track delivery progress using the provided tracking number. The endpoint returns full details to ensure accurate customer communication and logistics management without exposing sensitive system information.
   *
   * @param connection
   * @param shipmentId Unique identifier of the shipment to retrieve. This UUID corresponds to the shopping_mall_shipments.id field and cannot be modified or reused.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query shopping_mall_shipments table using shipmentId (UUID) as primary key. Return shipment record with carrier, tracking_number, status, and created_at fields. Validate that shipmentId exists and is not deleted. Return 404 if shipment not found. Do not join with order_items as shipmentId is unique primary key. Do not modify any data as this is a read-only operation.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("shipmentId")
    shipmentId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallShipment> {
    try {
      return await getShoppingMallCustomerShipmentsShipmentId({
        customer,
        shipmentId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Initiate delivery status confirmation for a shipment, either through customer action or system automation.
   *
   * This operation allows a customer to explicitly confirm delivery of their shipment, or triggers automatic delivery confirmation after 14 days of the shipment being marked as 'shipped'. The system enforces immutable status transitions: once a shipment is marked as 'delivered' or 'auto-delivered', it cannot be reverted.
   *
   * For customer-initiated delivery confirmation, the customer must provide a reason for delivery, which is permanently stored as part of the audit trail. This provides accountability and context for the delivery event. For automatic delivery, the system performs the transition without user input after the 14-day period expires, ensuring business continuity even when customers do not respond. Both transitions create permanent, unalterable records in the shipment status history.
   *
   * This operation is critical for inventory restoration workflows: when a shipment is confirmed delivered, the system automatically restores the inventory of the associated product variants. The operation's immutability ensures that delivery status cannot be manipulated after the fact, preserving the integrity of financial reconciliation and dispute resolution processes. It also directly connects to the order management system, where the delivery confirmation triggers eligibility for customer reviews and ratings.
   *
   * The customer must own the shipment being confirmed. System automation only initiates delivery confirmation when the shipment has been in 'shipped' status for 14 days, calculated from the shipment creation timestamp, not the estimated delivery date. Both delivery methods preserve the exact state of the shipment at time of transition in the immutable shopping_mall_shipments table, ensuring complete auditability.
   *
   * This operation is directly linked to the order item status logic described in 07-order-management.md, where delivery confirmation causes the associated order item to transition from 'shipped' to 'delivered'. This synchronization ensures consistent status across all related business entities within the shoppingMall ecosystem.
   *
   * @param connection
   * @param shipmentId The unique UUID identifier for the shipment record to update.
   * @param body Delivery confirmation input with status and optional reason.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Validate that the shipment exists and has status 'shipped'. If customer confirms delivery, transition status to 'delivered' with reason provided. If system triggers after 14 days, transition status to 'auto-delivered' without reason. For customer-initiated delivery confirmation, verify customer owns this shipment. For system-triggered delivery, verify 14 days have passed since shipment creation. Create immutable shipment status change record with timestamp and actor (customer or system). Return 400 if status is already 'delivered' or 'auto-delivered'. Return 404 if shipment does not exist or is not in 'shipped' status.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async updateDeliveryStatus(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("shipmentId")
    shipmentId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallShipment.IRequest,
  ): Promise<IShoppingMallShipment> {
    try {
      return await patchShoppingMallCustomerShipmentsShipmentId({
        customer,
        shipmentId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

