   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put()
  public async updatePassword(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IShoppingMallCustomerPasswordReset,
  ): Promise<void> {
    try {
      return await putShoppingMallCustomerReset({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

